class PropertyCard extends StatelessWidget { const PropertyCard({super.key,required this.property,required this.app}); final Property property;final _NikSpeedAppState app;@override Widget build(BuildContext context){final saved=app.saved.contains(property.id);return Card(clipBehavior:Clip.antiAlias,margin:const EdgeInsets.only(bottom:16),child:InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>PropertyPage(property:property,app:app))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(height:180,width:double.infinity,child:Image.network(property.imageUrl,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const ColoredBox(color:Color(0xffdde3dc))),),Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(property.type.toUpperCase(),style:const TextStyle(color:terracotta,fontSize:12,fontWeight:FontWeight.bold))),IconButton(icon:Icon(saved?Icons.favorite:Icons.favorite_border,color:terracotta),onPressed:(){app.setState(()=>saved?app.saved.remove(property.id):app.saved.add(property.id));})]),Text(property.title,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:5),Text('⌖ ${property.location}',style:const TextStyle(color:Colors.blueGrey)),const SizedBox(height:12),Text('${property.currency} ${ugx(property.price)}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17)),Text(property.bedrooms>0?'${property.bedrooms} beds · ${property.bathrooms} baths · ${property.area} ${property.areaUnit}':'${property.area} ${property.areaUnit}')])])])));}}

