class PropertyPage extends StatelessWidget { const PropertyPage({super.key,required this.property,required this.app});final Property property;final _NikSpeedAppState app;@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(),body:ListView(children:[SizedBox(height:280,child:Image.network(property.imageUrl,width:double.infinity,fit:BoxFit.cover)),Padding(padding:const EdgeInsets.all(22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(property.type.toUpperCase(),style:const TextStyle(color:terracotta,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text(property.title,style:const TextStyle(fontSize:30,fontWeight:FontWeight.w800)),Text('⌖ ${property.location}'),const SizedBox(height:20),Text('${property.currency} ${ugx(property.price)}',style:const TextStyle(fontSize:24,fontWeight:FontWeight.w800)),const SizedBox(height:15),Wrap(spacing:12,children:[Chip(label:Text(property.bedrooms>0?'${property.bedrooms} beds':'Land')),Chip(label:Text('${property.bathrooms} baths')),Chip(label:Text('${property.area} ${property.areaUnit}'))]),const SizedBox(height:22),const Text('About this property',style:TextStyle(fontSize:21,fontWeight:FontWeight.bold)),Text(property.description),const SizedBox(height:24),FilledButton.icon(onPressed:()=>showModalBottomSheet(context:context,isScrollControlled:true,builder:(_)=>EnquirySheet(property:property,app:app)),icon:const Icon(Icons.mail_outline),label:Text('Contact ${property.agentName}'))]))]));}

class EnquirySheet extends StatefulWidget { const EnquirySheet({super.key,required this.property,required this.app});final Property property;final _NikSpeedAppState app;@override State<EnquirySheet> createState()=>_EnquirySheetState();}class _EnquirySheetState extends State<EnquirySheet>{final form=GlobalKey<FormState>();final name=TextEditingController(),email=TextEditingController(),phone=TextEditingController(),message=TextEditingController();bool loading=false;Future<void> send()async{if(!form.currentState!.validate())return;setState(()=>loading=true);try{await widget.app.api.enquire(widget.property,{'name':name.text,'email':email.text,'phone':phone.text,'message':message.text});if(mounted){Navigator.pop(context);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Enquiry sent to the advertiser.')));}}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context)=>Padding(padding:EdgeInsets.fromLTRB(24,24,24,24+MediaQuery.of(context).viewInsets.bottom),child:Form(key:form,child:Column(mainAxisSize:MainAxisSize.min,children:[Text('Contact ${widget.property.agentName}',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),TextFormField(controller:name,decoration:const InputDecoration(labelText:'Your name'),validator:(v)=>v!.isEmpty?'Required':null),TextFormField(controller:email,decoration:const InputDecoration(labelText:'Email'),validator:(v)=>v!.contains('@')?null:'Enter a valid email'),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone number')),TextField(controller:message,decoration:const InputDecoration(labelText:'Message'),maxLines:2),const SizedBox(height:18),FilledButton(onPressed:loading?null:send,child:Text(loading?'Sending…':'Send enquiry'))])));}

class AdvertisePage extends StatefulWidget { const AdvertisePage({super.key,required this.app});final _NikSpeedAppState app;@override State<AdvertisePage> createState()=>_AdvertisePageState();}class _AdvertisePageState extends State<AdvertisePage>{late Future<List<ListingPlan>> plans;@override void initState(){super.initState();plans=widget.app.api.plans();}@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(20),children:[const Text('Advertise your property',style:TextStyle(fontSize:30,fontWeight:FontWeight.w800)),const SizedBox(height:8),const Text('Reach qualified buyers and tenants through a simple paid listing package.'),const SizedBox(height:22),FutureBuilder<List<ListingPlan>>(future:plans,builder:(context,snapshot){if(!snapshot.hasData)return const Center(child:Padding(padding:EdgeInsets.all(30),child:CircularProgressIndicator()));return Column(children:snapshot.data!.map((plan)=>Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(plan.name,style:const TextStyle(fontSize:21,fontWeight:FontWeight.bold)),Text('UGX ${ugx(plan.price)}',style:const TextStyle(fontSize:26,fontWeight:FontWeight.w800,color:terracotta)),Text('${plan.listings} listing credits · 30 days${plan.featured?' · Featured placement':''}'),const SizedBox(height:12),FilledButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AccountPage(app:widget.app,selectedPlan:plan))),child:const Text('Choose package'))]))).toList());})]);}

class AccountPage extends StatefulWidget { const AccountPage({super.key,required this.app,this.selectedPlan});final _NikSpeedAppState app;final ListingPlan? selectedPlan;@override State<AccountPage> createState()=>_AccountPageState();}class _AccountPageState extends State<AccountPage>{bool registering=false,loading=false;final name=TextEditingController(),email=TextEditingController(),password=TextEditingController();Future<void> auth()async{setState(()=>loading=true);try{final result=await widget.app.api.authenticate(register:registering,name:name.text,email:email.text,password:password.text);widget.app.login(result);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>DashboardPage(app:widget.app,selectedPlan:widget.selectedPlan)));}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context){if(widget.app.token!=null)return DashboardPage(app:widget.app,selectedPlan:widget.selectedPlan);return Scaffold(appBar:AppBar(title:const Text('Advertiser account')),body:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Text(registering?'Create your account':'Welcome back',style:const TextStyle(fontSize:28,fontWeight:FontWeight.w800)),if(registering)TextField(controller:name,decoration:const InputDecoration(labelText:'Name or agency')),TextField(controller:email,decoration:const InputDecoration(labelText:'Business email')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password (8+ characters)')),const SizedBox(height:20),FilledButton(onPressed:loading?null:auth,child:Text(loading?'Please wait…':registering?'Create account':'Sign in')),TextButton(onPressed:()=>setState(()=>registering=!registering),child:Text(registering?'Already registered? Sign in':'New advertiser? Create account'))])));}}
